// 读取冻结1000人全部八个命令边界核C域，没有执行完整世界步骤。
#include "background_support.hpp"
int main(int argc,char** argv){assert(argc==2);std::string root=argv[1];auto index=read_file(root+"/oracle-index.json");auto catalog=read_file(root+"/expanded-catalog.json");auto common=std::make_shared<const CommonCatalog>(checked(decode_common_catalog(*catalog.find("data"))));auto mcat=checked(decode_military_catalog(*catalog.find("data"),boundary::get_string(read_file(root+"/"+boundary::get_string(*index.find("initial_state"),"file","initial")),"scenario_id","state")));auto icat=checked(decode_interaction_catalog(*catalog.find("data"),common));std::vector<std::string> files{boundary::get_string(*index.find("initial_state"),"file","initial")};for(auto& command:*index.find("commands")->as<BoundaryValue::Array>())files.push_back(boundary::get_string(*command.find("after"),"file","after"));Integer boundaries=0;
    for(auto& file:files){auto source=read_file(root+"/"+file);auto military=checked(decode_military_seed(source));auto interaction=checked(decode_interaction_seed(source));compare_fragment(source,checked(export_military_state(military)));compare_fragment(source,checked(export_interaction_state(interaction)));
        CodecVisitor::Buffer mb,ib;CodecVisitor mw(mb);require(visit_military_checkpoint(mw,military));require(mw.finish());CodecVisitor iw(ib);require(visit_interaction_checkpoint(iw,interaction));require(iw.finish());MilitaryState mr;InteractionState ir;CodecVisitor mread(static_cast<const CodecVisitor::Buffer&>(mb)),iread(static_cast<const CodecVisitor::Buffer&>(ib));require(visit_military_checkpoint(mread,mr));require(mread.finish());require(visit_interaction_checkpoint(iread,ir));require(iread.finish());equal(checked(export_military_state(military)),checked(export_military_state(mr)),"military checkpoint");equal(checked(export_interaction_state(interaction)),checked(export_interaction_state(ir)),"interaction checkpoint");
        auto state=domain_common(source,*common);CommonStore c(std::move(state),common);InteractionAccess access;access.resolve_location=[&](const StableId& id){return checked(c.resolved_location(id));};access.role=[&](const StableId& id)->std::optional<RoleAssignmentView>{auto r=c.state().roles.find(id);if(!r)return {};return RoleAssignmentView{r->actor_id,r->enabled};};access.battle_occupied=[](auto&){return false;};access.terrain_point_valid=[](const auto&,const PointI& point){return point.x>=0&&point.x<=100000&&point.y>=0&&point.y<=100000;};access.journey_encounter=[&](const StableId& id)->Outcome<std::pair<StableId,bool>>{auto params=source.find("actions")->find(id)->find("params");auto e=params->find("encounter_id");auto p=params->find("paused");return {true,{e?boundary::string(*e,id):"",p?boundary::boolean(*p,id):false},{}};};MilitaryAccess ma;ma.interaction=&interaction;ma.interaction_catalog=&icat;ma.interaction_access=&access;ma.actor_injury=[&](auto& id){return c.state().actors.find(id)->injury;};ma.item_weight=[&](auto& id){return common->items.find(id)->weight;};require(validate_military_state(c,military,mcat,ma));require(validate_interaction_state(c,interaction,icat,access));
        if(c.tick()==4){assert(military.armies.size()==1&&military.armies[0].id=="army:2586");assert(military.actions.size()==1&&military.actions[0].action_id=="action:2916");auto departure=preview_military(c,military,mcat,ma,"actor.blackwater.commander",CampaignDepart{"campaign:2072"});assert(departure.ok&&departure.value.campaign_id=="campaign:2072");}
        ++boundaries;
    }
    assert(anchors_meet(icat,WildernessLocation{"m","o",{99999,99999}},WildernessLocation{"m","o",{99993,99999}}));assert(!anchors_meet(icat,WildernessLocation{"m","o",{99999,99999}},WildernessLocation{"m","o",{99993,99998}}));
    auto initial=read_file(root+"/"+files.front());initial.find("family")->find("children")->data=BoundaryValue::Dict{{"child",BoundaryValue{Integer(1)}}};auto unsupported=decode_interaction_seed(initial);assert(!unsupported.ok&&unsupported.error.kind==ErrorKind::unsupported_capability);
    std::cout<<"background_domains: PASS ("<<boundaries<<" real 1000-person boundaries; exact C-domain values, checkpoint roundtrip, validators, departure quote and float32 anchors)\n";
}
